import React from "react";

const CustomTable = ({ cols, rows, visibleCols = {} }) => {
  const getVisible = (key) => visibleCols[key] ?? true;
  const visibleColKeys = cols.filter((col) => getVisible(col.key));

  return (
    <div className="border border-gray-200 rounded-xl overflow-hidden w-full">
      {/* Shared horizontal scroll container */}
      <div className="overflow-x-auto">
        <div className="min-w-max">
          {/* Table header (sticky) */}
          <table className="table-fixed w-full border-collapse">
            <thead className="bg-[#E1D5C9] text-[#292929] text-sm sticky top-0 z-10">
              <tr>
                {visibleColKeys.map((col, i) => (
                  <th key={i} className="px-4 py-3 text-left whitespace-nowrap w-[200px]">
                    {col.label}
                  </th>
                ))}
                <th className="px-4 py-3 text-left whitespace-nowrap w-[150px]">
                  Actions
                </th>
              </tr>
            </thead>
          </table>

          {/* Scrollable tbody container */}
          <div className="max-h-[500px] overflow-y-auto">
            <table className="table-fixed w-full border-collapse">
              <tbody>
                {rows.map((row, rIndex) => (
                  <tr
                    key={rIndex}
                    className={`${
                      rIndex % 2 === 0 ? "bg-white" : "bg-[#F5EFEB]"
                    } text-[#292929] text-sm`}
                  >
                    {visibleColKeys.map((col, cIndex) => (
                      <td key={cIndex} className="px-4 py-3 whitespace-nowrap w-[200px]">
                        {col.render
                          ? col.render(row[col.key], row)
                          : row[col.key]}
                      </td>
                    ))}
                    <td className="px-4 py-3 whitespace-nowrap w-[150px]">
                      <div className="flex gap-3">
                        {row.actions || <span className="text-gray-400">—</span>}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CustomTable;
